=== file pagine/libri.php
<?php
// 1. Connessione
mysqli_report(MYSQLI_REPORT_OFF);
$host = "127.0.0.1";
$username = "root";
$password = "";
$nomedb = "biblioteca";
$connessione = mysqli_connect($host, $username, $password, $nomedb)
    or die("Connessione non riuscita: " . mysqli_connect_error());
// 2. Scrittura della query
$genere = $_GET["genere"];
$query = "SELECT Titolo, AnnoPubblicazione FROM Libri WHERE Genere = '$genere' ORDER BY Titolo";
// 3. Esecuzione
$risultato = mysqli_query($connessione, $query)
    or die("Errore nella query: " . mysqli_error($connessione));
// 4. Chiusura
mysqli_close($connessione);
// 5. Elaborazione
echo "<h1>Libri: $genere</h1>\n";
if (mysqli_num_rows($risultato) == 0) {
    echo "<p>Nessun libro.</p>\n";
} else {
    echo "<ul>\n";
    while ($riga = mysqli_fetch_array($risultato)) {
        echo "<li>$riga[Titolo] ($riga[AnnoPubblicazione])</li>\n";
    }
    echo "</ul>\n";
}
