<?php
// 1. Connessione
mysqli_report(MYSQLI_REPORT_OFF);
$host = "127.0.0.1";
$username = "root";
$password = "";
$nomedb = "biblioteca";
$connessione = mysqli_connect($host, $username, $password, $nomedb)
    or die("Connessione non riuscita: " . mysqli_connect_error());
// 2. Scrittura della query
$matricola = $_POST["matricola"];
$nome = $_POST["nome"];
$cognome = $_POST["cognome"];
$classe = $_POST["classe"];
$email = $_POST["email"];
$query = "INSERT INTO Studenti (Matricola, Nome, Cognome, Classe, Email) VALUES ($matricola, '$nome', '$cognome', '$classe', '$email')";
// 3. Esecuzione
mysqli_query($connessione, $query)
    or die("Errore nell'inserimento: " . mysqli_error($connessione));
// 4. Chiusura
mysqli_close($connessione);
// 5. Elaborazione
echo "<p>Registrato: $nome $cognome ($classe)</p>\n";
